"""
    Module with topology generator tool.

    Attributes:
        logger (logging.Logger): Global logging module instance.
"""

import sys
import copy
import uuid
import re
import bs4
from math import cos
from math import sin
from math import sqrt
from math import pi
from velocity_communicator.log.log import Log

''' abstract res'''


class Resource(object):
    '''
    Base class for Device, Port and Link
    '''
    logger = Log.get_logger('topology')

    @property
    def name(self):
        return self._name.string

    @name.setter
    def name(self, val):
        self._name.string = val

    @property
    def condition(self):
        return self._condition.string

    @condition.setter
    def condition(self, val):
        self._condition.string = val

    @property
    def id(self):
        return self.xml['id']

    @id.setter
    def id(self, val):
        self.xml['id'] = val

    @property
    def guid(self):
        return self.xml['guid']

    @guid.setter
    def guid(self, val):
        self.xml['guid'] = val

    def __str__(self):
        return self.name


''' other '''


class Link(Resource):
    '''
    Class for link in the topology.
    '''

    def __init__(self, data, type="xml"):
        if type == "xml":
            self.xml = data
            self._condition = self.xml.find("extensions", recursive=False)
            self._from = self.xml.find("endpoint", attrs={"direction": "unidirectional-from"})
            self._to = self.xml.find("endpoint", attrs={"direction": "unidirectional-to"})
            self._name = self.xml.find("property", attrs={"name": "name"})
            if self._from is None:
                tmp = self.xml.find_all("endpoint", attrs={"direction": "bidirectional"})
                self._from = tmp[0]
                self._to = tmp[1]
        elif type == "json":
            xml_template = '''<link id="">
            <property isimportant="false" name="name"></property>
            <property isimportant="false" name="type"></property>
            <property isimportant="false" name="abstractResourceId"/>
            <property isimportant="false" name="abstractResourceName"/>
            <endpoint direction="unidirectional-from" id=""/>
            <endpoint direction="unidirectional-to" id=""/>
            <extensions type="com.fnfr.rm.condition"/>
            </link>'''
            self.xml = bs4.BeautifulSoup(xml_template, "xml").link  # TODO: can be problematic
            self._condition = self.xml.find("extensions", recursive=False)
            self._name = self.xml.find("property", attrs={"name": "name"})
            self._type = self.xml.find("property", attrs={"name": "type"})
            self._from = self.xml.find("endpoint", attrs={"direction": "unidirectional-from"})
            self._to = self.xml.find("endpoint", attrs={"direction": "unidirectional-to"})
            self.id = uuid.uuid4().hex
            self.name = uuid.uuid4().hex
            if 'type' in data:
                self._type.string = data['type']
            self._from['id'] = data['from']
            self._to['id'] = data['to']
            self.condition = ""
            if 'condition' in data:
                self.condition = data['condition']
            self._from['direction'] = "bidirectional"
            self._to['direction'] = "bidirectional"
            if "direction" in data:
                self._from['direction'] = data['direction']
                self._to['direction'] = data['direction']
            if "name" in data:
                self.name = data["name"]

    def __copy__(self):
        return Link(copy.copy(self.xml))


class Port(Resource):
    '''
    Class for modeling port in velocity topology
    '''

    def __init__(self, data, str_type="xml"):
        if str_type == "xml":
            self.xml = data
            self._name = self.xml.find("property", attrs={"name": "name"})
            self._condition = self.xml.find("extensions", recursive=False)
            self.can_modify = True
            if self._condition is None:
                self.can_modify = False
        elif str_type == "json":
            xml_template = '''<resource guid="" id="" type="port">
            <property isimportant="false" name="name"></property>
            <property isimportant="false" name="description"/>
            <property isimportant="false" name="connectivity"></property>
            <extensions type="com.fnfr.rm.condition" xs:namespace="com.fnfr.rm.condition"></extensions>
            <property name="inventoryName"/>
            </resource>'''
            self.xml = bs4.BeautifulSoup(xml_template, "xml").resource  # TODO: Can be problematic
            self._condition = self.xml.find("extensions", recursive=False)
            self.can_modify = True
            self._name = self.xml.find("property", attrs={"name": "name"})
            if "name" in data:
                self.name = data['name']
            self.condition = ""
            if 'condition' in data:
                self.condition = data['condition']
            self.id = uuid.uuid4().hex
            self.guid = uuid.uuid4().hex

    def __copy__(self):
        return Port(copy.copy(self.xml))

    def __str__(self):
        return self.name


class VirtualPort(Resource):
    '''
    Class for modeling port in topology
    '''

    def __init__(self, data="", str_type="xml", **kwargs):
        if str_type == "xml":
            if data == "":
                self.logger.error("var data at VirtualPort constructor is empty.")
            self.xml = data
            self._name = self.xml.find("property", attrs={"name": "name"})
        elif str_type == "json":
            xml_template = '''<resource guid="" id="" type="virtual_port">
<property isimportant="false" name="name"></property>
<property isimportant="false" name="description"/>
<propertyCollection name="Initial Configuration" order="0">
<property description="Current status of object." editable="false" id="statusId" iscloudspecific="false" isimportant="false" name="Status" order="0" required="false" type="TEXT"/>
</propertyCollection>
<propertyCollection name="Networking" order="1">
<property description="The MAC address. If you do not specify a value, the MAC address will be assigned automatically." editable="true" id="macAddressId" iscloudspecific="false" isimportant="false" name="MAC address" order="0" required="false" type="MAC_ADDRESS"/>
<property description="Internal IP address used for communication between instances in the same cloud." editable="true" id="privateIpId" iscloudspecific="false" isimportant="true" name="IP address" order="1" required="false" type="IP_ADDRESS"/>
<property description="Public network from which to allocate the public IP for the port. Virtual machine must have a route to the selected public network." editable="true" id="assignPublicIpId" iscloudspecific="false" isimportant="false" name="Public IP network" order="2" required="false" type="DROP_DOWN_TOPOLOGY_VIRTUAL_PUBLIC_NETWORK"/>
<property description="Public IP that gets allocated from the public network IP pool." editable="false" id="publicIpId" iscloudspecific="false" isimportant="true" name="Public IP" order="3" required="false" type="IP_ADDRESS"/>
</propertyCollection>
<property name="inventoryName"/>
</resource>'''
            self.xml = bs4.BeautifulSoup(xml_template, "xml").resource  # TODO: Can be problematic
            self._name = self.xml.find("property", attrs={"name": "name"})
            self.id = uuid.uuid4().hex
        self._mac_addr = self.xml.find("property", attrs={"id": "macAddressId"})
        self._private_ip = self.xml.find("property", attrs={"id": "privateIpId"})
        self._public_ip = self.xml.find("property", attrs={"id": "publicIpId"})
        if "name" in kwargs:
            self.name = kwargs['name']
        if "vm_id" in kwargs:
            self.guid = kwargs['vm_id']
        if "private_ip" in kwargs:
            self.private_ip = kwargs['private_ip']
        if "mac_addr" in kwargs:
            self.mac_addr = kwargs["mac_addr"]
        if "public_ip" in kwargs:
            self.public_ip = kwargs["public_ip"]
        if "public_network" in kwargs:
            self.public_network = kwargs["public_network"]

    @property
    def mac_addr(self):
        return self._mac_addr.string

    @mac_addr.setter
    def mac_addr(self, val):
        self._mac_addr.string = val

    @property
    def private_ip(self):
        return self._private_ip.string

    @private_ip.setter
    def private_ip(self, val):
        self._private_ip.string = val

    @property
    def public_ip(self):
        return self._public_ip.string

    @public_ip.setter
    def public_ip(self, val):
        self._public_ip.string = val

    @property
    def public_network(self):
        return self._public_network.string

    @public_network.setter
    def public_network(self, val):
        self._public_network.string = val

    def __str__(self):
        return self.name

    @property
    def guid(self):
        return self.xml['guid']

    @guid.setter
    def guid(self, val):
        self.vm_id = val
        self.xml['guid'] = "VIRTUAL_MACHINE_PORT:" + self.vm_id


class Vlan(Resource):
    _template = '''
    <resource guid="" id="" shared="false" type="vlan">
<boundary height="100" width="130" x="" y=""/>
<property isimportant="false" name="name"></property>
<property isimportant="false" name="description"/>
<property isimportant="false" name="iconURI">platform:/plugin/com.fnfr.itest.topology.tbml.edit/icons/full/topology/Device_generic_32.gif</property>
<propertyCollection name="ID" order="null">
<property description="VLAN ID. Example: 302" editable="true" id="id" iscloudspecific="false" isimportant="true" name="ID" order="null" required="false" type="VLAN_ID"></property>
</propertyCollection>
</resource>
'''

    def __init__(self, xml=None, **kwargs):
        if isinstance(xml, bs4.Tag):
            self.xml = xml
        elif xml is None:
            self.xml = bs4.BeautifulSoup(self._template, "xml").resource
            self.xml["guid"] = uuid.uuid4().hex
            self.xml["id"] = uuid.uuid4().hex
        self.boundary = self.xml.find("boundary", recursive=False)
        self._name = self.xml.find("property", attrs={"name": "name"})
        self._vlan_id = self.xml.find("property", attrs={"type": "VLAN_ID"})
        if "name" in kwargs:
            self.name = kwargs["name"]
        if "vlan_id" in kwargs:
            self.vlan_id = kwargs["vlan_id"]

    def get_port_ids(self):
        return [self.id]

    def get_diameter(self):
        return sqrt(float(self.boundary["height"]) ** 2 + float(self.boundary["width"]) ** 2)

    @property
    def vlan_id(self):
        return self._vlan_id.string

    @vlan_id.setter
    def vlan_id(self, val):
        self._vlan_id.string = str(val)


